(() => {
'use strict';const $=s=>document.querySelector(s),core=window.RadicalLesson;
function math(host,source){const span=document.createElement('span');span.dataset.tex=source;host.replaceChildren(span);}
function root(){const a=Number($('#root-radicand').value),n=Number($('#root-index').value),v=core.nthRoot(a,n);if(v===null){math($('#root-equation'),`\\sqrt[${n}]{${a}}\\notin\\mathbb R`);$('#root-feedback').textContent='Radikan negatif dengan indeks genap tidak mempunyai akar real. Kita tidak menampilkan nilai kompleks dalam lab ini.';return;}const exact=Math.abs(v-Math.round(v))<1e-10;const value=exact?String(Math.round(v)):v.toFixed(6).replace('.', '{,}');math($('#root-equation'),`\\sqrt[${n}]{${a}}${exact?'=':'\\approx'}${value}`);$('#root-feedback').textContent=(n%2===0?'Akar genap memilih nilai utama yang tidak negatif. ':'Akar ganjil memiliki tanda yang sama dengan radikannya. ')+(exact?'Hasil pada contoh ini adalah bilangan bulat tepat.':'Desimal ditampilkan sebagai pendekatan sampai enam angka di belakang koma.');}
$('#root-index').addEventListener('change',root);$('#root-radicand').addEventListener('change',root);root();
function simplify(){const n=Number($('#simplify-radicand').value),s=core.simplify(n);$('#simplify-output').value=n;math($('#simplify-equation'),`\\sqrt{${n}}=\\sqrt{${s.outside*s.outside}\\times${s.inside}}=${core.texRoot(n)}`);$('#simplify-feedback').textContent=s.outside===1?'Tidak ada faktor kuadrat sempurna lebih besar dari satu. Bentuk ini sudah sederhana.':`Faktor kuadrat sempurna terbesar adalah ${s.outside*s.outside}. Akar faktor itu adalah ${s.outside}, yang dikeluarkan dari tanda akar.`;}
$('#simplify-radicand').addEventListener('input',simplify);simplify();
const powers={eight:[String.raw`8^{2/3}=(\sqrt[3]8)^2=2^2=4`,'Penyebut tiga memberi akar pangkat tiga; pembilang dua memberi kuadrat setelah akar diambil.'],sixteen:[String.raw`16^{3/4}=(\sqrt[4]{16})^3=2^3=8`,'Ambil akar pangkat empat dahulu, lalu pangkatkan tiga.'],negative:[String.raw`27^{-2/3}=\frac1{(\sqrt[3]{27})^2}=\frac19`,'Tanda negatif berada pada pangkat: hasilnya kebalikan, bukan bilangan negatif.'],half:[String.raw`9^{1/2}=\sqrt9=3`,'Akar kuadrat utama sembilan bernilai tiga, bukan tambah atau kurang tiga.']};
function power(){const [tex,reason]=powers[$('#power-example').value];math($('#power-equation'),tex);$('#power-feedback').textContent=reason;}$('#power-example').addEventListener('change',power);power();
const rationalizations={simple:[String.raw`\frac1{\sqrt2}=\frac{\sqrt2}{2}`,'Kalikan pembilang dan penyebut dengan akar dua. Penyebut menjadi dua.'],simplify:[String.raw`\frac3{\sqrt{12}}=\frac{3\sqrt{12}}{12}=\frac{\sqrt3}{2}`,'Kalikan dengan akar dua belas pada pembilang dan penyebut; sederhanakan akar dua belas menjadi dua akar tiga, lalu sederhanakan faktor bilangannya.'],minus:[String.raw`\frac1{\sqrt3-1}=\frac{\sqrt3+1}{3-1}=\frac{\sqrt3+1}{2}`,'Sekawannya akar tiga ditambah satu. Hasil kali penyebut dengan sekawannya adalah tiga dikurangi satu.'],plus:[String.raw`\frac1{\sqrt2+1}=\frac{\sqrt2-1}{2-1}=\sqrt2-1`,'Sekawannya akar dua dikurangi satu. Penyebut hasil perkalian bernilai satu.']};
function rationalize(){const [tex,reason]=rationalizations[$('#rationalize-example').value];math($('#rationalize-equation'),tex);$('#rationalize-feedback').textContent=reason;}$('#rationalize-example').addEventListener('change',rationalize);rationalize();
const questions=[
[String.raw`\sqrt[3]{-27}=?`,[String.raw`-3`,String.raw`3`,String.raw`\text{Tidak real}`],0,'Negatif tiga dipangkatkan tiga menghasilkan negatif dua puluh tujuh. Indeks ganjil menerima radikan negatif.'],
[String.raw`\sqrt[4]{16}=?`,[String.raw`\pm2`,String.raw`2`,String.raw`4`],1,'Akar genap utama adalah dua. Dua solusi tambah/kurang dua merupakan jawaban persamaan pangkat empat, bukan nilai simbol akar utama.'],
[String.raw`\sqrt{72}=?`,[String.raw`36\sqrt2`,String.raw`6\sqrt2`,String.raw`8\sqrt3`],1,'Tujuh puluh dua adalah tiga puluh enam dikali dua, sehingga faktor yang keluar adalah enam.'],
[String.raw`\sqrt{12}+\sqrt{27}=?`,[String.raw`\sqrt{39}`,String.raw`5\sqrt3`,String.raw`5\sqrt{39}`],1,'Sederhanakan menjadi dua akar tiga ditambah tiga akar tiga. Gabungkan koefisien suku sejenis.'],
[String.raw`27^{-2/3}=?`,[String.raw`-9`,String.raw`9`,String.raw`\frac19`],2,'Akar pangkat tiga dari dua puluh tujuh adalah tiga. Kuadratkan, kemudian ambil kebalikannya karena pangkat negatif.'],
[String.raw`\frac1{\sqrt2}=?`,[String.raw`\frac{\sqrt2}{2}`,String.raw`\sqrt2`,String.raw`\frac12`],0,'Mengalikan pembilang dan penyebut dengan akar dua menghasilkan akar dua dibagi dua.'],
[String.raw`\frac1{\sqrt3-1}=?`,[String.raw`\sqrt3+1`,String.raw`\frac{\sqrt3+1}{2}`,String.raw`\frac{\sqrt3-1}{2}`],1,'Kalikan dengan sekawan pada pembilang dan penyebut. Penyebut menjadi tiga dikurangi satu, yaitu dua.'],
[String.raw`\frac1{\sqrt x}=\frac{\sqrt x}{x}\quad\text{dengan syarat?}`,[String.raw`x\ge0`,String.raw`x\ne0`,String.raw`x>0`],2,'Radikan harus tidak negatif, dan akar pada penyebut tidak boleh nol. Gabungannya adalah masukan positif.']
];const solved=new Set();
questions.forEach(([tex,options,answer,reason],i)=>{const box=document.createElement('fieldset'),legend=document.createElement('legend'),number=document.createElement('span'),formula=document.createElement('span');number.dataset.noEquation='';number.textContent=`Latihan ${i+1}: `;formula.dataset.tex=tex;legend.append(number,formula);box.append(legend);options.forEach((option,j)=>{const label=document.createElement('label'),radio=document.createElement('input'),copy=document.createElement('span');radio.type='radio';radio.name=`radical-q${i}`;radio.value=String(j);copy.dataset.tex=option;label.append(radio,copy);box.append(label);});const button=document.createElement('button');button.type='button';button.textContent='Periksa jawaban';const feedback=document.createElement('p');feedback.setAttribute('role','status');button.addEventListener('click',()=>{const selected=box.querySelector('input:checked');if(!selected){feedback.textContent='Pilih satu jawaban terlebih dahulu.';return;}const ok=Number(selected.value)===answer;if(ok)solved.add(i);feedback.textContent=(ok?'Tepat. ':'Belum tepat. ')+reason;feedback.className=ok?'correct':'incorrect';$('#radical-progress').textContent=`${solved.size} dari 8 latihan pernah dijawab tepat.`;});box.addEventListener('change',()=>{feedback.textContent='Jawaban berubah. Periksa kembali untuk melihat tanggapan.';feedback.className='';});box.append(button,feedback);$('#radical-questions').append(box);});$('#radical-progress').textContent='0 dari 8 latihan pernah dijawab tepat.';
try{$('#radical-reflection').value=localStorage.getItem('fondasi-radical-reflection')||'';}catch{$('#radical-save').textContent='Catatan belum dapat dimuat. Salin bila diperlukan.';}
$('#radical-reflection').addEventListener('input',()=>{try{localStorage.setItem('fondasi-radical-reflection',$('#radical-reflection').value);$('#radical-save').textContent='Catatan tersimpan di peramban ini.';}catch{$('#radical-save').textContent='Catatan belum dapat disimpan. Salin bila diperlukan.';}});
})();
